def solve():
    while True:
        n = int(input())
        if n == 0:
            break

        # Build adjacency list
        adj = {}
        for _ in range(n):
            a, b = map(int, input().split())
            if a not in adj:
                adj[a] = []
            if b not in adj:
                adj[b] = []
            adj[a].append(b)
            adj[b].append(a)

        # Find longest simple path using backtracking
        max_length = 0

        def backtrack(node, path):
            nonlocal max_length
            max_length = max(max_length, len(path))

            for neighbor in adj[node]:
                if neighbor not in path:
                    path.add(neighbor)
                    backtrack(neighbor, path)
                    path.remove(neighbor)

        # Try each node as starting point
        for start in adj:
            path = {start}
            backtrack(start, path)

        print(max_length)

solve()
