import sys

def solve():
    data = sys.stdin.read().strip().split()
    t = int(data[0])
    results = []

    for i in range(1, t + 1):
        s = data[i]
        freq = {}
        for c in s:
            freq[c] = freq.get(c, 0) + 1

        # For lexicographically maximum, we want to keep characters that appear later in the alphabet first
        # So we iterate from 'z' to 'a'
        result = []
        for c in reversed(range(ord('a'), ord('z') + 1)):
            char = chr(c)
            if freq.get(char, 0) > 1:
                # Keep one occurrence
                result.append(char)
                freq[char] = 1
            elif freq.get(char, 0) == 1:
                # Keep the one occurrence
                result.append(char)

        results.append(''.join(result))

    sys.stdout.write('\n'.join(results))

if __name__ == '__main__':
