# Find connected components for Mocha's forest
parent_mocha = list(range(n + 1))

def find_mocha(u):
    while parent_mocha[u] != u:
        parent_mocha[u] = parent_mocha[parent_mocha[u]]
        u = parent_mocha[u]
    return u

def union_mocha(u, v):
    pu = find_mocha(u)
    pv = find_mocha(v)
    if pu != pv:
        parent_mocha[pu] = pv

for _ in range(m1):
    u, v = map(int, input().split())
    union_mocha(u, v)

# Find connected components for Diana's forest
parent_diana = list(range(n + 1))

def find_diana(u):
    while parent_diana[u] != u:
        parent_diana[u] = parent_diana[parent_diana[u]]
        u = parent_diana[u]
    return u

def union_diana(u, v):
    pu = find_diana(u)
    pv = find_diana(v)
    if pu != pv:
        parent_diana[pu] = pv

for _ in range(m2):
    u, v = map(int, input().split())
    union_diana(u, v)

