components_mocha = {}
for i in range(1, n + 1):
    components_mocha[i] = find_mocha(i)

components_diana = {}
for i in range(1, n + 1):
    components_diana[i] = find_diana(i)

# Find edges that can be added
edges = []
for u in range(1, n + 1):
    for v in range(u + 1, n + 1):
        if components_mocha[u] != components_mocha[v] and components_diana[u] != components_diana[v]:
            edges.append((u, v))

# Output the result
print(len(edges))
for u, v in edges:
    print(u, v)
