def solve():
    n = int(input())
    points = []
    for _ in range(n):
        p, c = input().split()
        points.append((int(p), c))

    # Sort points by position
    points.sort()

    # Separate points by color
    red = []
    green = []
    blue = []

    for p, c in points:
        if c == 'R':
            red.append(p)
        elif c == 'G':
            green.append(p)
        else:
            blue.append(p)

    # If there are no green points, we can't satisfy the constraints
    if not green:
        print(0)
        return

    # Connect red points among themselves
    red_edges = []
    for i in range(len(red) - 1):
        red_edges.append((red[i], red[i + 1]))

    # Connect blue points among themselves
    blue_edges = []
    for i in range(len(blue) - 1):
        blue_edges.append((blue[i], blue[i + 1]))

    # Connect red points to green points
    red_green_edges = []
    for r in red:
        for g in green:
            red_green_edges.append((r, g))

    # Connect blue points to green points
    blue_green_edges = []
    for b in blue:
        for g in green:
            blue_green_edges.append((b, g))

    # Calculate total cost
    total_cost = 0

    # Add red edges
    for r1, r2 in red_edges:
        total_cost += abs(r1 - r2)

    # Add blue edges
    for b1, b2 in blue_edges:
        total_cost += abs(b1 - b2)

    # Add red-green edges
    for r, g in red_green_edges:
        total_cost += abs(r - g)

    # Add blue-green edges
    for b, g in blue_green_edges:
        total_cost += abs(b - g)

    print(total_cost)

solve()
