import sys

def solve() -> None:
    a, b = map(int, sys.stdin.readline().split())

    # If a > b, we need an odd interval where odd_count = a and even_count = b
    if a > b:
        n = 2 * b + 1
        if (n + 1) // 2 == a:
            print("YES")
        else:
            print("NO")
    # If b > a, we need an odd interval where odd_count = b and even_count = a
    elif b > a:
        n = 2 * a + 1
        if (n + 1) // 2 == b:
            print("YES")
        else:
            print("NO")
    # If a == b, we need an even interval where odd_count = a and even_count = b
    else:
        n = 2 * a
        if n // 2 == a and n // 2 == b:
            print("YES")
        else:
            print("NO")

if __name__ == "__main__":
    solve()
