result = 1

# For each prime, find the minimum max exponent across pairs
# We'll use a frequency array for primes up to 200,000
max_val = 200000
prime_freq = [[] for _ in range(max_val + 1)]

for num in a:
    # Factorize num
    temp = num
    for p in range(2, int(temp**0.5) + 1):
        if temp % p == 0:
            count = 0
            while temp % p == 0:
                temp //= p
                count += 1
            prime_freq[p].append(count)
    if temp > 1:
        prime_freq[temp].append(1)

for p in range(2, max_val + 1):
    if len(prime_freq[p]) >= 2:
        # We have at least two numbers with this prime
        # Find the minimum max exponent across pairs
        exponents = prime_freq[p]
        exponents.sort()
        # The minimum max exponent is the second largest exponent
        min_max_exp = exponents[-2]
        result *= p ** min_max_exp

print(result)
