    n, k = map(int, input().split())

    # For even n, no conflicts
    if n % 2 == 0:
        print(k)
    else:
        # For odd n, conflicts happen at hour (n+1)/2
        # B's position at hour k:
        # - If k < (n+1)/2, position = k
        # - If k == (n+1)/2, position = k + 1
        # - If k > (n+1)/2, position = k - 1
        mid = (n + 1) // 2
        if k < mid:
            print(k)
        elif k == mid:
            print(k + 1)
        else:
            print(k - 1)
