def solve():
    MOD = 10**9 + 7

    # Read input
    N, L = map(int, input().split())
    A = list(map(int, input().split()))

    # Precompute p_max for all i from 1 to L
    p_max = [0] * (L + 1)  # 1-indexed

    for i in range(2, L + 1):
        # Find prime factorization of i
        temp = i
        factors = {}

        # Check for primes up to sqrt(temp)
        for prime in range(2, int(temp**0.5) + 1):
            if temp % prime == 0:
                count = 0
                while temp % prime == 0:
                    temp //= prime
                    count += 1
                factors[prime] = count

        # If remaining temp is > 1, it's a prime factor
        if temp > 1:
            factors[temp] = 1

        # Find p_max
        max_exponent = -1
        p_max_val = None
        for prime, exp in factors.items():
            if exp > max_exponent or (exp == max_exponent and prime < p_max_val):
                max_exponent = exp
                p_max_val = prime

        p_max[i] = p_max_val

    # Perform operations
    for i in range(1, L + 1):
        if i == 1 or p_max[i] % i % 2 == 1:
            # Beneficial: double the largest element
            if A:
                max_val = max(A)
                idx = A.index(max_val)
                A[idx] *= 2
        else:
            # Harmful: divide the smallest element
            if A:
                min_val = min(A)
                idx = A.index(min_val)
                A[idx] //= 2

        # Remove elements that became 0
        A = [x for x in A if x != 0]

    # Output
    print(len(A))
    if A:
        print(' '.join(str(x % MOD) for x in sorted(A)))
    else:
        print()

solve()
