def shortest_supersequence_length(cities):
    n = len(cities)

    # dp[mask][i] = minimum length of merged string that includes cities in mask and ends with character at position i of some city
    # We'll use a dictionary to store states

    # Initial state: no cities included, ends with character at position -1 (none)
    dp = {(-1, 0): 0}  # (end_position, city_index): length

    for mask in range(1 << n):
        for end_pos, city_idx in list(dp.keys()):
            length = dp[(end_pos, city_idx)]

            # Try adding each city that hasn't been included yet
            for j in range(n):
                if not (mask & (1 << j)):
                    # City j hasn't been included
                    city = cities[j]

                    # Try extending the merged string by adding characters from city j
                    for k in range(len(city)):
                        # Try ending with character at position k of city j
                        new_mask = mask | (1 << j)
                        new_end_pos = k
                        new_length = length + k + 1  # Add characters from position end_pos+1 to k

                        # Update dp
                        if (new_end_pos, j) not in dp or dp[(new_end_pos, j)] > new_length:
                            dp[(new_end_pos, j)] = new_length

    # Find the minimum length for all cities included
    min_length = float('inf')
    for end_pos, city_idx in dp:
        if dp[(end_pos, city_idx)] < min_length:
            min_length = dp[(end_pos, city_idx)]

    return min_length

# Read input
import sys

for line in sys.stdin:
    line = line.strip()
    if not line:
        continue

    n = int(line)
    if n == 0:
        break

    cities = []
    for _ in range(n):
        cities.append(sys.stdin.readline().strip())

    result = shortest_supersequence_length(cities)
    print(result)
"}

