# Check all possible segments
for left in range(n):
    window_counts = {}
    distinct_count = 0

    for right in range(left, n):
        element = a[right]

        # Add element to window
        if element in window_counts:
            window_counts[element] += 1
        else:
            window_counts[element] = 1
            distinct_count += 1

        # Check if this window has exactly k distinct elements
        if distinct_count == k:
            # Check if this window is minimal by inclusion
            is_minimal = True

            # Try to remove each element and see if we can still maintain k distinct elements
            for i in range(left, right + 1):
                # Create a copy of window_counts
                temp_counts = window_counts.copy()
                temp_counts[a[i]] -= 1
                if temp_counts[a[i]] == 0:
                    del temp_counts[a[i]]

                # Check if we still have exactly k distinct elements
                if len(temp_counts) == k:
                    is_minimal = False
                    break

            if is_minimal:
                print(left + 1, right + 1)
                exit()

# If we didn't find any valid segment
print("-1 -1")
