def modinv(a, m):
    """Modular multiplicative inverse using Fermat's little theorem"""
    return pow(a, m - 2, m)

def comb(n, k, mod, fact, inv_fact):
    """Compute combination C(n, k) modulo mod"""
    if n < 0 or k < 0 or k > n:
        return 0
    return fact[n] * inv_fact[k] % mod * inv_fact[n - k] % mod

# Precompute factorials and inverse factorials up to 10^5 + 1
max_n = 10**5 + 1
mod = 10**9 + 7
fact = [1] * max_n
for i in range(1, max_n):
    fact[i] = fact[i-1] * i % mod

inv_fact = [1] * max_n
inv_fact[max_n - 1] = modinv(fact[max_n - 1], mod)
for i in range(max_n - 2, -1, -1):
    inv_fact[i] = inv_fact[i + 1] * (i + 1) % mod

q = int(input())
for _ in range(q):
    n, f = map(int, input().split())

    # Total compositions of n into f parts
    total = comb(n - 1, f - 1, mod, fact, inv_fact)

    # Subtract compositions where all parts have a common divisor > 1
    answer = total

    # Find all divisors of n
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)

    for d in divisors:
        if d > 1:
            # Number of compositions where all parts are multiples of d
            # This is equivalent to compositions of n/d into f parts
            answer = (answer - comb((n // d) - 1, f - 1, mod, fact, inv_fact)) % mod

    print(answer)
