def is_k_beautiful(x_str, k):
    """Check if a number string is k-beautiful"""
    return len(set(x_str)) <= k

def find_min_k_beautiful(n, k):
    """Find the minimum k-beautiful number ≥ n"""
    n_str = str(n)
    length = len(n_str)

    # Try numbers with the same length as n
    for i in range(length):
        # Try all combinations of digits for the first i positions
        # This is getting complex... let me think of a simpler approach

    # For k=1, try all numbers with a single repeated digit
    if k == 1:
        for d in range(1, 10):
            candidate = int(str(d) * length)
            if candidate >= n:
                return candidate
        # If none found with same length, try increasing length
        for length in range(length + 1, 10):
            for d in range(1, 10):
                candidate = int(str(d) * length)
                return candidate

    # For k=2, try all combinations of 2 digits
    if k == 2:
        # Try all pairs of digits (first digit can't be 0)
        for d1 in range(1, 10):
